; bios.asm -- chapter 17: the BIOS's routine, every frame
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "bios.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A program that does nothing but wait for the next frame, in mode 1: the
; BIOS's routine takes every interrupt.
init:   di
        ld sp, SYS_AREA
        im 1
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
main:   halt                    ; the BIOS's routine runs, and comes back here
        jr main
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
